-### Install locally (from this repo)
+### Install from this repository
+
+Build the CLI before installing it globally from a checkout:

 ```bash
+npm ci
+npm run build
 npm install -g .
 ```

-### Install published package
+### Install the published package

 ```bash
 npm install -g @madkoo/dfiles
 ```

+Global npm executables are installed in `$(npm prefix -g)/bin` on macOS and Linux, and in `$(npm prefix -g)` on Windows. Make sure the matching directory is in your `PATH` (`Path` on Windows). If `dfiles` is not found, add that directory to your `PATH` and open a new terminal.
+
+After global installation, you can run `dfiles` from any directory. Commands that use a manifest (`add`, `pull`, `status`, `list`, and `remove`) still need a `dfiles.json` in the current directory or one of its parent directories. `init` and `upgrade` do not need an existing manifest.
+
 ## Quick start
*** Add File: tests/cli.test.ts
+import { spawnSync } from 'node:child_process';
+import * as fs from 'node:fs';
+import * as os from 'node:os';
+import * as path from 'node:path';
+import { afterEach, describe, expect, it } from 'vitest';
+
+const tempDirs: string[] = [];
+
+function makeTempDir(): string {
+  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'dfiles-cli-test-'));
+  tempDirs.push(dir);
+  return dir;
+}
+
+afterEach(() => {
+  for (const dir of tempDirs) {
+    fs.rmSync(dir, { recursive: true, force: true });
+  }
+  tempDirs.length = 0;
+});
+
+describe('CLI executable', () => {
+  it('is registered for npm installs and runs from outside the repository', () => {
+    const repoRoot = process.cwd();
+    const packageJson: { bin?: Record<string, string> } = JSON.parse(
+      fs.readFileSync(path.join(repoRoot, 'package.json'), 'utf8'),
+    );
+
+    expect(packageJson.bin?.dfiles).toBe('./dist/index.js');
+
+    const result = spawnSync(
+      process.execPath,
+      [
+        '-r',
+        path.join(repoRoot, 'node_modules', 'ts-node', 'register'),
+        path.join(repoRoot, 'src', 'index.ts'),
+        '--help',
+      ],
+      { cwd: makeTempDir(), encoding: 'utf8' },
+    );
+
+    expect(result.error).toBeUndefined();
+    expect(result.status).toBe(0);
+    expect(result.stdout).toContain('Usage: dfiles');
+  });
+});
*** End Patch

